removeDecorationsByType(decorationTypeKey) {
        // remove decorations for type and sub type
        const oldDecorationsIds = this.Eb[decorationTypeKey];
        if (oldDecorationsIds) {
            this.changeDecorations(accessor => accessor.deltaDecorations(oldDecorationsIds, []));
        }
        if (this.Eb.hasOwnProperty(decorationTypeKey)) {
            delete this.Eb[decorationTypeKey];
        }
        if (this.Fb.hasOwnProperty(decorationTypeKey)) {
            delete this.Fb[decorationTypeKey];
        }
    }
